/**
 * Admin contracts: provisioning of tables.
 *
 * These endpoints live under `/api/v1/admin/tables` and need a session of an
 * account with the `admin` role (`Authorization: Bearer <accessToken>`).
 *
 * A table's id is generated by the server and cannot be chosen or changed by
 * the caller, so the create and update requests carry no `id`.
 */

import { z } from 'zod';
import { tableIdSchema } from './table.js';

/** Fields an admin can set on a table. Shared by create and update. */
const displayNameSchema = z.string().trim().min(1).max(100);
const locationSchema = z.string().trim().min(1).max(200);

/**
 * A table as stored: the registration record, without live state.
 *
 * Mode, connection and the active job come from the driver and are exposed by
 * the public `Table` resource instead.
 */
export const adminTableSchema = z.object({
  id: tableIdSchema,
  displayName: displayNameSchema,
  location: locationSchema,
  enabled: z.boolean(),
  createdAt: z.string(),
  updatedAt: z.string(),
});
export type AdminTable = z.infer<typeof adminTableSchema>;

/** Body of `POST /api/v1/admin/tables`. */
export const createTableRequestSchema = z.object({
  displayName: displayNameSchema,
  location: locationSchema,
  /** A new table is enabled unless the admin says otherwise. */
  enabled: z.boolean().default(true),
});
export type CreateTableRequest = z.input<typeof createTableRequestSchema>;

/** Payload of `POST /api/v1/admin/tables` (`201`). */
export const createTableResponseSchema = adminTableSchema;
export type CreateTableResponse = AdminTable;

/** Payload of `GET /api/v1/admin/tables`. */
export const listAdminTablesResponseSchema = z.object({
  tables: z.array(adminTableSchema),
});
export type ListAdminTablesResponse = z.infer<typeof listAdminTablesResponseSchema>;

/** Payload of `GET /api/v1/admin/tables/:tableId`. */
export const getAdminTableResponseSchema = adminTableSchema;
export type GetAdminTableResponse = AdminTable;

/**
 * Body of `PATCH /api/v1/admin/tables/:tableId`.
 *
 * Every field is optional but at least one must be present, so an empty patch
 * is a validation error rather than a silent no-op. Unknown keys, including
 * `id`, are stripped.
 */
export const updateTableRequestSchema = z
  .object({
    displayName: displayNameSchema.optional(),
    location: locationSchema.optional(),
    enabled: z.boolean().optional(),
  })
  .refine(
    (patch) =>
      patch.displayName !== undefined ||
      patch.location !== undefined ||
      patch.enabled !== undefined,
    { message: 'Provide at least one of displayName, location or enabled.' },
  );
export type UpdateTableRequest = z.infer<typeof updateTableRequestSchema>;

/** Payload of `PATCH /api/v1/admin/tables/:tableId`: the updated table. */
export const updateTableResponseSchema = adminTableSchema;
export type UpdateTableResponse = AdminTable;

/**
 * Payload of `GET /api/v1/admin/tables/:tableId/qr`.
 *
 * `link` is what the QR code encodes: `https://<domain>/t/<tableId>` in
 * production. It contains only the public table id. A QR code is never proof of
 * authorisation, and this response must not grow a token or signature field
 * without a deliberate access-control decision.
 */
export const tableQrResponseSchema = z.object({
  tableId: tableIdSchema,
  link: z.url(),
});
export type TableQrResponse = z.infer<typeof tableQrResponseSchema>;
